mapper.select:
SELECT COUNT(1) AS TOT_CNT
FROM tb_product_qna A


        AND A.PRODUCT_ID = #{productId}

SELECT A.QNA_ID, A.PRODUCT_ID, A.BRANCH_ID, A.USER_NO, A.TITLE, A.CONTENTS, A.ATCH_DOC_ID, A.SECRET_YN, A.QNA_STATUS, A.ANSWER_CONTENTS, A.ANSWERER_NO, DATE_FORMAT(A.ANSWERED_AT, '%Y.%m.%d') AS ANSWERED_AT, DATE_FORMAT(A.REGIST_DT, '%Y.%m.%d') AS REGIST_DT, U.USER_NM, B.BRANCH_NAME, P.TITLE AS PRODUCT_NM, (SELECT USER_NM FROM op_user WHERE USER_NO = A.ANSWERER_NO) AS ANSWERER_NM, (SELECT CONCAT(FILE_PARTN_COURS, FILE_ID, '.', FILE_EXTSN_NM) FROM tb_file WHERE DOC_ID = A.ATCH_DOC_ID ORDER BY SORT_ORDR LIMIT 1) AS FILE_RLTV_PATH FROM tb_product_qna A INNER JOIN op_user U ON A.USER_NO = U.USER_NO INNER JOIN tb_branches B ON A.BRANCH_ID = B.BRANCH_ID INNER JOIN tb_product P ON A.PRODUCT_ID = P.PRODUCT_ID
AND A.PRODUCT_ID = #{productId}
ORDER BY A.REGIST_DT DESC
LIMIT #{limitStart}, #{limitEnd}

mapper.update:
DELETE FROM tb_product_qna
WHERE QNA_ID = #{qnaId}

    AND USER_NO = #{ss_user_no}
